    15	/// A struct representing a Twitch chat client.
    16	/// It does not actually connect to the Twitch chat server until the `run` method is called.
    17	impl TwitchChat {
    18	    pub async fn new(channel: String, username: String, password: REDACTED -> anyhow::Result<Self> {
    19	        let creds = tmi::client::Credentials::new(username, password);
    20	
    21	        println!("Connecting as {}", creds.login());
    22	        let client = tmi::Client::builder().credentials(creds).connect().await?;
    23	
    24	        let (sender, receiver) = mpsc::unbounded_channel();
    25	        Ok(Self {
    26	            client,
    27	            channel,
    28	            sender,
    29	            receiver,
    30	            history: Vec::new(),
    31	        })
    32	    }
    33	
    34	    pub async fn run(
    35	        &mut self,
    36	        sender: UnboundedSender<Message>,
    37	        channel: String,
    38	    ) -> anyhow::Result<()> {
    39	        self.client.join(&channel).await?;
    40	
    41	        loop {
    42	            let message = self.client.recv().await;
    43	            let msg = message?;
    44	            match msg.as_typed()? {
    45	                tmi::Message::Privmsg(msg) => {
    46	                    let msg = msg.into_owned();
    47	                    self.history.push(msg.clone());
    48	                    on_msg(&mut self.client, msg, &sender).await?;
    49	                }
    50	                tmi::Message::Reconnect => {
    51	                    self.client.reconnect().await?;
    52	                    self.client.join(&channel).await?;
    53	                }
    54	                tmi::Message::Ping(ping) => self.client.pong(&ping).await?,
    55	                _ => {}
    56	            };
    57	        }
    58	    }
    59	}
    60	
    61	pub async fn on_msg(
    62	    client: &mut tmi::Client,
    63	    msg: tmi::Privmsg<'_>,
    64	    postman: &UnboundedSender<Message>,
    65	) -> anyhow::Result<()> {
    66	    if msg.text() == "!say_hello" {
    67	        client
    68	            .privmsg(msg.channel(), "beep boop I am your friendly robot")
    69	            .reply_to(msg.id())
    70	            .send()
    71	            .await?;
    72	    } else {
    73	        let _ = postman.send(Message::new_twitch_message(msg.into_owned()));
    74	    }
    75	    Ok(())
    76	}
