107	    17	impl TwitchChat {
108	    18	    pub async fn new(channel: String, username: String, password: REDACTED -> anyhow::Result<Self> {
109	    19	        let creds = tmi::client::Credentials::new(username, password);
110	    20	
111	    21	        println!("Connecting as {}", creds.login());
112	    22	        let client = tmi::Client::builder().credentials(creds).connect().await?;
113	    23	
114	    24	        let (sender, receiver) = mpsc::unbounded_channel();
115	    25	        Ok(Self {
116	    26	            client,
117	    27	            channel,
118	    28	            sender,
119	    29	            receiver,
120	    30	            history: Vec::new(),
121	    31	        })
122	    32	    }
123	    33	
124	    34	    pub async fn run(
125	    35	        &mut self,
126	    36	        sender: UnboundedSender<Message>,
127	    37	        channel: String,
128	    38	    ) -> anyhow::Result<()> {
129	    39	        self.client.join(&channel).await?;
130	    40	
131	    41	        loop {
132	    42	            let message = self.client.recv().await;
133	    43	            let msg = message?;
134	    44	            match msg.as_typed()? {
135	    45	                tmi::Message::Privmsg(msg) => {
136	    46	                    let msg = msg.into_owned();
137	    47	                    self.history.push(msg.clone());
138	    48	                    on_msg(&mut self.client, msg, &sender).await?;
139	    49	                }
140	    50	                tmi::Message::Reconnect => {
141	    51	                    self.client.reconnect().await?;
142	    52	                    self.client.join(&channel).await?;
143	    53	                }
144	    54	                tmi::Message::Ping(ping) => self.client.pong(&ping).await?,
145	    55	                _ => {}
146	    56	            };
147	    57	        }
148	    58	    }
149	    59	}
