    43	pub async fn run_server(opts: &ServerArgs) -> anyhow::Result<()> {
    44	    let client: HelixClient<'static, _> =
    45	        twitch_api::HelixClient::with_client(auth::http_client()?);
    46	    let mut auth = auth::TokenManager::load(client.get_client().clone(), &opts.twitch).await?;
    47	    let token = auth.token.clone();
    48	    let user_id = if let Some(ref id) = opts.twitch.channel_id {
    49	        id.clone().into()
    50	    } else if let Some(ref login) = opts.twitch.channel_login {
    51	        client
    52	            .get_user_from_login(login, &*token.read().await)
    53	            .await?
    54	            .ok_or_else(|| anyhow::anyhow!("no user found with name {login}"))?
    55	            .id
    56	    } else {
    57	        token.read().await.user_id.clone()
    58	    };
    59	    anyhow::ensure!(
    60	        user_id == token.read().await.user_id,
    61	        "authorize as the broadcaster whose alerts you want to monitor"
    62	    );
    63	
    64	    let Some(gpt_key) = opts.llm.openai.openai_key.clone() else {
    65	        anyhow::bail!("GPT key is required");
    66	    };
    67	
    68	    // set up sqlite database
    69	    // TODO: Make this required in the args you fool
    70	    let Some(db_path) = opts.db_path.clone() else {
    71	        anyhow::bail!("db path is required");
    72	    };
    73	
    74	    let sqlite_pool =
    75	        sql_common::setup::setup_sqlite_migrations(db_path.clone(), &MIGRATIONS).await?;
    76	
    77	    let (sender, receiver) = mpsc::unbounded_channel();
    78	    let (frontend_sender, frontend_receiver) = mpsc::unbounded_channel();
    79	
    80	    let ai_manager = AIManager::new(
    81	        sqlite_pool,
    82	        gpt_key,
    83	        opts.llm.openai.openai_model.clone(),
    84	        frontend_sender,
    85	    )?;
    86	
    87	    let mut twitch_client = WebsocketClient {
    88	        session_id: None,
    89	        token,
    90	        client,
    91	        user_id,
    92	        connect_url: twitch_api::TWITCH_EVENTSUB_WEBSOCKET_URL.clone(),
    93	        sender,
    94	    };
    95	
    96	    println!(
    97	        "Starting frontend api on http port: {} and ws port: {}, and host name: {}",
    98	        opts.http.port, opts.ws.ws_port, opts.ws.ws_host,
    99	    );
   100	
   101	    let host_info = HostInfo {
   102	        websocket_host: opts.ws.ws_host.clone(),
   103	        ws_port: opts.ws.ws_port,
   104	        http_port: opts.http.port,
   105	        http_host: opts.http.host.clone(),
   106	    };
   107	
   108	    let frontend_api = FrontendApi::new(host_info, opts.frontend_assets.clone());
   109	
   110	    tokio::try_join!(
   111	        auth.run(),
   112	        twitch_client.run(),
   113	        ai_manager.run(receiver),
   114	        frontend_api.run(frontend_receiver),
   115	    )?;
   116	    Ok(())
