    13	/// Log file path: `TWITCH_ALERTS_LOG`, then `NULL_TWITCH_LOG`, else `twitch_alerts.log`.
    14	/// Logs go to stderr and to this file (append mode); use the file when a TUI owns the terminal.
    15	fn install_tracing() -> anyhow::Result<()> {
    16	    use tracing_error::ErrorLayer;
    17	    use tracing_subscriber::prelude::*;
    18	    use tracing_subscriber::{fmt, EnvFilter};
    19	
    20	    let log_path: PathBuf = std::env::var_os("TWITCH_ALERTS_LOG")
    21	        .or_else(|| std::env::var_os("NULL_TWITCH_LOG"))
    22	        .filter(|s| !s.is_empty())
    23	        .map(PathBuf::from)
    24	        .unwrap_or_else(|| PathBuf::from("twitch_alerts.log"));
    25	
    26	    if let Some(dir) = log_path.parent() {
    27	        if !dir.as_os_str().is_empty() {
    28	            std::fs::create_dir_all(dir)
    29	                .with_context(|| format!("create log dir {}", dir.display()))?;
    30	        }
    31	    }
    32	
    33	    let log_file = std::fs::OpenOptions::new()
    34	        .create(true)
    35	        .append(true)
    36	        .open(&log_path)
    37	        .with_context(|| format!("open log file {}", log_path.display()))?;
    38	
    39	    let fmt_stderr = fmt::layer()
    40	        .with_file(true)
    41	        .with_line_number(true)
    42	        .with_target(true);
    43	
    44	    let fmt_file = fmt::layer()
    45	        .with_writer(Mutex::new(log_file))
    46	        .with_file(true)
    47	        .with_line_number(true)
    48	        .with_target(true)
    49	        .with_ansi(false);
    50	
    51	    let mut filter_layer =
    52	        EnvFilter::try_from_default_env().or_else(|_| EnvFilter::try_new("info"))?;
    53	    for directive in [
    54	        "hyper=error",
    55	        "h2=error",
    56	        "rustls=error",
    57	        "tungstenite=error",
    58	        "want=info",
    59	        "reqwest=info",
    60	        "mio=info",
    61	    ] {
    62	        filter_layer = filter_layer.add_directive(directive.parse()?);
    63	    }
    64	
    65	    tracing_subscriber::registry()
    66	        .with(filter_layer)
    67	        .with(fmt_stderr)
    68	        .with(fmt_file)
    69	        .with(ErrorLayer::default())
    70	        .try_init()
    71	        .map_err(|error| anyhow::anyhow!("initialize tracing: {error}"))?;
    72	
    73	    tracing::info!(path = %log_path.display(), "tracing file sink enabled");
    74	    Ok(())
    75	}
