    87	#[tracing::instrument(skip(client, opts))]
    88	pub async fn get_access_token(
    89	    client: &reqwest::Client,
    90	    opts: &crate::opts::TwitchBotArgs,
    91	) -> anyhow::Result<UserToken> {
    92	    if let Some(ref access_token) = opts.access_token {
    93	        make_token(client, access_token.to_string()).await
    94	    } else if let (Some(ref oauth_service_url), Some(ref pointer)) =
    95	        (&opts.oauth2_service_url, &opts.oauth2_service_pointer)
    96	    {
    97	        tracing::info!(
    98	            "using oauth service on `{}` to get oauth token",
    99	            oauth_service_url
   100	        );
   101	
   102	        let mut request = client.get(oauth_service_url.as_str());
   103	        if let Some(ref key) = opts.oauth2_service_key {
   104	            request = request.bearer_auth(key.secret());
   105	        }
   106	        let request = request.build()?;
   107	
   108	        match client.execute(request).await {
   109	            Ok(response)
   110	                if !(response.status().is_client_error()
   111	                    || response.status().is_server_error()) =>
   112	            {
   113	                let service_response: serde_json::Value = response.json().await?;
   114	                make_token(
   115	                    client,
   116	                    service_response
   117	                        .pointer(pointer)
   118	                        .ok_or_else(|| {
   119	                            anyhow::format_err!("could not get a field on `{}`", pointer)
   120	                        })?
   121	                        .as_str()
   122	                        .ok_or_else(|| anyhow::format_err!("token is not a string"))?
   123	                        .to_string(),
   124	                )
   125	                .await
   126	            }
   127	            Ok(response_error) => {
   128	                let status = response_error.status();
   129	                anyhow::bail!("oauth service returned error code: {}", status);
   130	            }
   131	            Err(e) => Err(e).context("calling OAuth service"),
   132	        }
   133	    } else {
   134	        anyhow::bail!("an access token or OAuth service URL and token pointer are required")
   135	    }
   136	}
