    83	async fn receive_messages(
    84	    mut receiver: mpsc::UnboundedReceiver<DisplayMessage>,
    85	    queues: &EventQueues,
    86	) -> anyhow::Result<()> {
    87	    while let Some(message) = receiver.recv().await {
    88	        queue_message(queues, message);
    89	    }
    90	    anyhow::bail!("alert message channel closed")
    91	}
    92	
    93	fn queue_message(queues: &EventQueues, message: DisplayMessage) {
    94	    let mut queues = queues.lock().expect("event queue lock poisoned");
    95	    queues.unpublished_events.push_back(message.clone());
    96	    queues.latest_events.push_back(message);
    97	    if queues.latest_events.len() > 10 {
    98	        queues.latest_events.pop_front();
    99	    }
   100	}
   101	
   102	fn next_message(queues: &EventQueues) -> Option<DisplayMessage> {
   103	    if !types::EVENT_QUEUE_ACTIVE.load(std::sync::atomic::Ordering::SeqCst) {
   104	        return None;
   105	    }
   106	    queues
   107	        .lock()
   108	        .expect("event queue lock poisoned")
   109	        .unpublished_events
   110	        .pop_front()
   111	}
