84	    83	async fn receive_messages(
85	    84	    mut receiver: mpsc::UnboundedReceiver<DisplayMessage>,
86	    85	    queues: &EventQueues,
87	    86	) -> anyhow::Result<()> {
88	    87	    while let Some(message) = receiver.recv().await {
89	    88	        queue_message(queues, message);
90	    89	    }
91	    90	    anyhow::bail!("alert message channel closed")
92	    91	}
