94	    93	fn queue_message(queues: &EventQueues, message: DisplayMessage) {
95	    94	    let mut queues = queues.lock().expect("event queue lock poisoned");
96	    95	    queues.unpublished_events.push_back(message.clone());
97	    96	    queues.latest_events.push_back(message);
98	    97	    if queues.latest_events.len() > 10 {
99	    98	        queues.latest_events.pop_front();
100	    99	    }
101	   100	}
102	   101	
103	   102	fn next_message(queues: &EventQueues) -> Option<DisplayMessage> {
104	   103	    if !types::EVENT_QUEUE_ACTIVE.load(std::sync::atomic::Ordering::SeqCst) {
105	   104	        return None;
106	   105	    }
107	   106	    queues
108	   107	        .lock()
109	   108	        .expect("event queue lock poisoned")
110	   109	        .unpublished_events
111	   110	        .pop_front()
112	   111	}
113	   112	
114	   113	fn broadcast(connections: &ConnectionMap, message: Message) {
115	   114	    connections
116	   115	        .lock()
117	   116	        .expect("connection lock poisoned")
118	   117	        .retain(|peer, sender| {
119	   118	            let connected = sender.unbounded_send(message.clone()).is_ok();
120	   119	            if !connected {
121	   120	                tracing::debug!(%peer, "Removing disconnected browser");
122	   121	            }
123	   122	            connected
124	   123	        });
125	   124	}
