127	   126	async fn process_events(queues: &EventQueues, connections: &ConnectionMap) -> anyhow::Result<()> {
128	   127	    loop {
129	   128	        let Some(message) = next_message(queues) else {
130	   129	            tokio::time::sleep(std::time::Duration::from_millis(500)).await;
131	   130	            continue;
132	   131	        };
133	   132	        let html = html! {
134	   133	            div id="notifications" class="alert" hx-swap="afterend" hx-target="notifications" {
135	   134	                div class="wrapper" {
136	   135	                    (htmx::get_display_html(&message))
137	   136	                }
138	   137	            }
139	   138	        };
140	   139	        broadcast(connections, Message::Text(html.into()));
141	   140	        tokio::time::sleep(std::time::Duration::from_secs(10)).await;
142	   141	        let html = html! {
143	   142	            div id="notifications" hx-swap="delete" hx-target="notifications" {}
144	   143	        };
145	   144	        broadcast(connections, Message::Text(html.into()));
146	   145	        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
147	   146	    }
