150	   149	async fn accept_connections(listener: TcpListener, state: ConnectionMap) -> anyhow::Result<()> {
151	   150	    // Dropping the set cancels active browser connections when the server stops.
152	   151	    let mut connections = JoinSet::new();
153	   152	    loop {
154	   153	        tokio::select! {
155	   154	            connection = listener.accept() => {
156	   155	                let (stream, peer) = connection.context("accept browser WebSocket")?;
157	   156	                connections.spawn(accept_connection(peer, stream, state.clone()));
158	   157	            }
159	   158	            Some(result) = connections.join_next(), if !connections.is_empty() => {
160	   159	                result.context("browser connection task failed")?;
161	   160	            }
162	   161	        }
163	   162	    }
164	   163	}
