166	   165	async fn accept_connection(peer: SocketAddr, stream: TcpStream, state: ConnectionMap) {
167	   166	    let result = handle_connection(peer, stream, &state).await;
168	   167	    state
169	   168	        .lock()
170	   169	        .expect("connection lock poisoned")
171	   170	        .remove(&peer);
172	   171	    if let Err(error) = result {
173	   172	        match error {
174	   173	            Error::ConnectionClosed | Error::Protocol(_) | Error::Utf8 => (),
175	   174	            error => tracing::warn!(%peer, %error, "Browser WebSocket failed"),
176	   175	        }
177	   176	    }
178	   177	}
179	   178	
180	   179	async fn handle_connection(
181	   180	    peer: SocketAddr,
182	   181	    stream: TcpStream,
183	   182	    state: &ConnectionMap,
184	   183	) -> Result<()> {
185	   184	    let socket = accept_async(stream).await?;
186	   185	    let (sender, mut receiver) = unbounded();
187	   186	    state
188	   187	        .lock()
189	   188	        .expect("connection lock poisoned")
190	   189	        .insert(peer, sender);
191	   190	    let (mut socket_sender, mut socket_receiver) = socket.split();
192	   191	    loop {
193	   192	        tokio::select! {
194	   193	            message = socket_receiver.next() => {
195	   194	                let Some(message) = message else { break };
196	   195	                let message = message?;
197	   196	                if message.is_text() || message.is_binary() {
198	   197	                    socket_sender.send(message).await?;
199	   198	                } else if message.is_close() {
200	   199	                    break;
201	   200	                }
202	   201	            }
203	   202	            message = receiver.next() => {
204	   203	                let Some(message) = message else { break };
205	   204	                socket_sender.send(message).await?;
206	   205	            }
207	   206	        }
208	   207	    }
209	   208	    Ok(())
210	   209	}
