    13	fn main() -> anyhow::Result<()> {
    14	    tokio::runtime::Builder::new_multi_thread()
    15	        .worker_threads(32)
    16	        .enable_all()
    17	        .build()?
    18	        .block_on(run())
    19	}
    20	
    21	async fn run() -> anyhow::Result<()> {
    22	    utils::install_utils()?;
    23	    let cmd = Cli::parse();
    24	
    25	    tracing::debug!("Starting bruce {}", env!("CARGO_PKG_VERSION"));
    26	
    27	    match cmd.command {
    28	        Commands::Game(opts) => {
    29	            run_game(&opts).await?;
    30	        }
    31	    }
    32	
    33	    Ok(())
    34	}
    35	
    36	pub async fn run_game(opts: &GamesSubCommand) -> anyhow::Result<()> {
    37	    match opts {
    38	        GamesSubCommand::Wordle(args) => {
    39	            let mut twitch = get_twitch_chat(&args.twitch).await?;
    40	            let (chat_sender, chat_receiver) = tokio::sync::mpsc::unbounded_channel();
    41	            let channel = args.twitch.channel.clone();
    42	            tokio::spawn(async move {
    43	                match twitch.run(chat_sender, channel).await {
    44	                    Ok(()) => {}
    45	                    Err(e) => tracing::error!(error = %e, "Twitch chat task exited with error"),
    46	                }
    47	            });
    48	
    49	            let sqlite_pool =
    50	                sql_common::setup::setup_sqlite_migrations(args.db_path.clone(), &MIGRATIONS)
    51	                    .await?;
    52	            let word_list = WordList::from(args.word_list.as_str());
    53	
    54	            // Anathema's `runtime.run` blocks a thread for the whole session. Running it on a
    55	            // Tokio worker can strand `tokio::spawn` tasks (e.g. `game_loop`, IRC) on that same
    56	            // worker, so drive the TUI from the blocking pool instead.
    57	            tokio::task::spawn_blocking(move || {
    58	                crate::wordle::game::start_game(chat_receiver, word_list, sqlite_pool)
    59	            })
    60	            .await
    61	            .map_err(|e| anyhow::anyhow!("Wordle TUI thread panicked or was cancelled: {e}"))??;
    62	        }
    63	        GamesSubCommand::Dragons(_) => {
    64	            anyhow::bail!("Dragons game is not implemented yet");
    65	        }
    66	    }
    67	    Ok(())
    68	}
    69	
    70	pub async fn get_twitch_chat(opts: &TwitchChatArgs) -> anyhow::Result<TwitchChat> {
    71	    let chat = TwitchChat::new(
    72	        opts.channel.clone(),
    73	        opts.tc_username.clone(),
    74	        opts.tc_password.clone(),
    75	    )
    76	    .await?;
    77	    Ok(chat)
    78	}
