    12	pub async fn get_player_score(
    13	    pool: &SqlitePool,
    14	    platform: MessagePlatform,
    15	    user_id: &str,
    16	    username: &str,
    17	) -> anyhow::Result<UserScore> {
    18	    let mut connection = pool.acquire().await?;
    19	    let platform = platform as u8;
    20	    if let Some(score) = sqlx::query_as::<_, UserScore>(
    21	        "SELECT id, total_points FROM wordle_highscores WHERE platform = ? AND platform_user_id = ?",
    22	    )
    23	    .bind(platform)
    24	    .bind(user_id)
    25	    .fetch_optional(&mut *connection)
    26	    .await?
    27	    {
    28	        return Ok(score);
    29	    }
    30	
    31	    Ok(sqlx::query_as::<_, UserScore>(
    32	        "INSERT INTO wordle_highscores (username, platform_user_id, platform, total_points)
    33	         VALUES (?, ?, ?, 0) RETURNING id, total_points",
    34	    )
    35	    .bind(username)
    36	    .bind(user_id)
    37	    .bind(platform)
    38	    .fetch_one(&mut *connection)
    39	    .await?)
