107	   107	    leader_board: Pool<Sqlite>,
108	   108	) -> anyhow::Result<()> {
109	   109	    let doc = Document::new("@index");
110	   110	    let mut backend = TuiBackend::builder()
111	   111	        .enable_raw_mode()
112	   112	        .enable_mouse()
113	   113	        .hide_cursor()
114	   114	        .clear()
115	   115	        .finish()
116	   116	        .context("initialize Wordle terminal")?;
117	   117	    backend.finalize();
118	   118	
119	   119	    let mut builder = Runtime::builder(doc, &backend);
120	   120	
121	   121	    let twitch_chat_id = builder
122	   122	        .default::<Messages>(
123	   123	            "messages",
124	   124	            include_str!("templates/message.aml").to_template(),
125	   125	        )
126	   126	        .context("register messages component")?;
127	   127	
128	   128	    builder
129	   129	        .prototype(
130	   130	            "stack",
131	   131	            include_str!("templates/row.aml").to_template(),
132	   132	            || Row,
133	   133	            RowState::default,
134	   134	        )
135	   135	        .context("register row component")?;
136	   136	
137	   137	    let main_id = builder
138	   138	        .component(
139	   139	            "index",
140	   140	            include_str!("templates/main.aml").to_template(),
141	   141	            Index,
142	   142	            IndexState::default(),
143	   143	        )
144	   144	        .context("register index component")?;
145	   145	    let emitter = builder.emitter();
146	   146	    let game_task = tokio::spawn(async move {
147	   147	        if let Err(error) = game_loop(
148	   148	            chat,
149	   149	            main_id,
150	   150	            twitch_chat_id,
151	   151	            emitter,
152	   152	            get_spell_checker(word_list),
153	   153	            word_list,
154	   154	            leader_board,
155	   155	        )
156	   156	        .await
157	   157	        {
158	   158	            tracing::error!(%error, "Wordle game loop stopped");
159	   159	        }
160	   160	    });
161	   161	    let result = builder.finish(&mut backend, |runtime, backend| runtime.run(backend));
162	   162	    game_task.abort();
163	   163	    result.context("run Wordle terminal")
164	   164	}
