183	   183	async fn game_loop(
184	   184	    mut chat: UnboundedReceiver<Message>,
185	   185	    main_id: ComponentId<IndexMessage>,
186	   186	    twitch_chat_id: ComponentId<ChatMessages>,
187	   187	    emitter: Emitter,
188	   188	    spell_checker: HashSet<String>,
189	   189	    word_list: WordList,
190	   190	    leader_board: Pool<Sqlite>,
191	   191	) -> anyhow::Result<()> {
192	   192	    let guess_duration = std::time::Duration::from_secs(GAME_ROUND_TIME_LIMIT as u64);
193	   193	    refresh_leader_board(&leader_board, &emitter, main_id).await?;
194	   194	    loop {
195	   195	        let mut correct_cells = [Cell::default(); 5];
196	   196	        let mut round_count = 0;
197	   197	        increment_round_count(&mut round_count, &emitter, main_id).await?;
198	   198	        // Not actually "starting" the game now.
199	   199	        let mut start_time = std::time::Instant::now();
200	   200	        update_timer(GAME_ROUND_TIME_LIMIT, &emitter, main_id).await?;
201	   201	
202	   202	        let word = get_random_word(word_list);
203	   203	
204	   204	        let mut game_round = GameRound::new(word, &spell_checker);
205	   205	        let mut game_over = false;
206	   206	        let mut round_started = false;
207	   207	
208	   208	        // Play a round
209	   209	        while round_count <= 6 && !game_over {
210	   210	            // Process incoming messages from the chat
211	   211	            // TODO: Currently if processing falls behind the game will not progress to next round
212	   212	            while let Ok(message) = chat.try_recv() {
213	   213	                let player = Player::from(&message);
214	   214	                let guess = message.content();
215	   215	                let valid = game_round.new_guess(player.clone(), guess);
216	   216	                if valid && player.is_scored() {
217	   217	                    let score =
218	   218	                        get_player_score(&leader_board, player.platform, &player.id, &player.name)
219	   219	                            .await?;
220	   220	                    tracing::debug!(
221	   221	                        player_id = score.id,
222	   222	                        total_points = score.total_points,
223	   223	                        "Wordle player registered"
224	   224	                    );
225	   225	                }
226	   226	                // emit the chat message to the twitch chat component
227	   227	                if valid && !round_started {
228	   228	                    round_started = true;
229	   229	                    start_time = std::time::Instant::now();
230	   230	                }
231	   231	
232	   232	                emitter
233	   233	                    .emit_async(
234	   234	                        twitch_chat_id,
235	   235	                        ChatMessages::new(
236	   236	                            message.sender().to_string(),
237	   237	                            message.content().to_string(),
238	   238	                            message.platform(),
239	   239	                        ),
240	   240	                    )
241	   241	                    .await
242	   242	                    .context("send chat message")?;
243	   243	            }
244	   244	
245	   245	            if !round_started {
246	   246	                // If the round has not started, we can wait for a message to start the round
247	   247	                tokio::time::sleep(std::time::Duration::from_millis(1000)).await;
248	   248	                continue;
249	   249	            }
250	   250	
251	   251	            // Check if the time limit for the current guess has been reached
252	   252	            if start_time.elapsed() >= guess_duration {
253	   253	                // increment the guess count and reset the timer
254	   254	                let winning_word = game_round.select_round_winner(word);
255	   255	
256	   256	                // Update the UI with the winning word
257	   257	                let row_message = game_round.build_cells(winning_word.unwrap_or([97; 5]));
258	   258	                emitter
259	   259	                    .emit(
260	   260	                        main_id,
261	   261	                        IndexMessage::Row(RowUpdate {
262	   262	                            row: round_count,
263	   263	                            row_message,
264	   264	                        }),
265	   265	                    )
266	   266	                    .context("send winning word")?;
267	   267	
268	   268	                update_correct_cells(&mut correct_cells, &row_message.data);
269	   269	
270	   270	                // Everyone who voted for the word on the board shares its points.
271	   271	                if let Some(winning_word) = winning_word {
272	   272	                    let points = score_row(&row_message.data, round_count);
273	   273	                    let awarded =
274	   274	                        award_points(&leader_board, game_round.voters_for(winning_word), points)
275	   275	                            .await?;
276	   276	                    if awarded {
277	   277	                        refresh_leader_board(&leader_board, &emitter, main_id).await?;
278	   278	                    }
279	   279	                }
280	   280	
281	   281	                emitter
282	   282	                    .emit_async(
283	   283	                        main_id,
284	   284	                        IndexMessage::Row(RowUpdate {
285	   285	                            row: 7, // Solution row
286	   286	                            row_message: RowMessage {
287	   287	                                data: correct_cells,
288	   288	                            },
289	   289	                        }),
290	   290	                    )
291	   291	                    .await
292	   292	                    .context("send winning word")?;
293	   293	                game_over = row_message
294	   294	                    .data
295	   295	                    .iter()
296	   296	                    .all(|cell| cell.status == LetterStatus::Correct);
297	   297	
298	   298	                // They won
299	   299	                if game_over {
300	   300	                    break;
301	   301	                }
302	   302	                // Reset the game round for the next guess
303	   303	                start_time = std::time::Instant::now();
304	   304	                update_timer(GAME_ROUND_TIME_LIMIT, &emitter, main_id).await?;
305	   305	
306	   306	                next_round(
307	   307	                    &mut round_count,
308	   308	                    &emitter,
309	   309	                    main_id,
310	   310	                    &mut game_round,
311	   311	                    &mut round_started,
312	   312	                )
313	   313	                .await?;
314	   314	                continue;
315	   315	            }
316	   316	
317	   317	            // Emit the timer update
318	   318	            let timer = (guess_duration.as_secs() - start_time.elapsed().as_secs()) as u8;
319	   319	            update_timer(timer, &emitter, main_id).await?;
320	   320	
321	   321	            // If no messages are received, we can continue the game loop
322	   322	            if start_time.elapsed() <= guess_duration {
323	   323	                tokio::time::sleep(std::time::Duration::from_millis(100)).await;
324	   324	            }
325	   325	        }
326	   326	
327	   327	        // Toggle bit has a bug in this UI threading.
328	   328	        // messages are not recived in the order they are sent
329	   329	        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
330	   330	
331	   331	        //update the UI with the final state of the game
332	   332	        for i in 0..5 {
333	   333	            if correct_cells[i].status != LetterStatus::Correct {
334	   334	                correct_cells[i] = Cell {
335	   335	                    letter: word[i],
336	   336	                    status: LetterStatus::Absent,
337	   337	                };
338	   338	            }
339	   339	        }
340	   340	
341	   341	        emitter
342	   342	            .emit_async(
343	   343	                main_id,
344	   344	                IndexMessage::Row(RowUpdate {
345	   345	                    row: 7, // Solution row
346	   346	                    row_message: RowMessage {
347	   347	                        data: correct_cells,
348	   348	                    },
349	   349	                }),
350	   350	            )
351	   351	            .await
352	   352	            .context("send winning word")?;
353	   353	        // build correct cells from the winning word
354	   354	        tokio::time::sleep(std::time::Duration::from_secs(30)).await;
355	   355	        // Reset the board for the next round
356	   356	        update_timer(GAME_ROUND_TIME_LIMIT, &emitter, main_id).await?;
357	   357	        reset_board(&emitter, main_id).await?;
358	   358	    } // Game loop
359	   359	}
