361	   361	/// Points earned by a row: 2 per correctly placed letter, 1 per letter in the wrong spot,
362	   362	/// plus a solve bonus of 40 minus 5 for every row used (row 1 = 35, row 6 = 10).
363	   363	fn score_row(cells: &[Cell; 5], row: u8) -> u32 {
364	   364	    let letter_points: u32 = cells
365	   365	        .iter()
366	   366	        .map(|cell| match cell.status {
367	   367	            LetterStatus::Correct => CORRECT_LETTER_POINTS,
368	   368	            LetterStatus::Present => PRESENT_LETTER_POINTS,
369	   369	            LetterStatus::Absent => 0,
370	   370	        })
371	   371	        .sum();
372	   372	    let solved = cells
373	   373	        .iter()
374	   374	        .all(|cell| cell.status == LetterStatus::Correct);
375	   375	    let solve_bonus = if solved {
376	   376	        SOLVE_BONUS_BASE.saturating_sub(SOLVE_BONUS_PENALTY_PER_ROW * u32::from(row))
377	   377	    } else {
378	   378	        0
379	   379	    };
380	   380	    letter_points + solve_bonus
381	   381	}
