383	   383	/// Returns whether any stored score changed.
384	   384	async fn award_points(
385	   385	    leader_board: &Pool<Sqlite>,
386	   386	    players: Vec<&Player>,
387	   387	    points: u32,
388	   388	) -> anyhow::Result<bool> {
389	   389	    if points == 0 {
390	   390	        return Ok(false);
391	   391	    }
392	   392	    let mut awarded = false;
393	   393	    for player in players.into_iter().filter(|player| player.is_scored()) {
394	   394	        awarded = true;
395	   395	        let score = add_points(
396	   396	            leader_board,
397	   397	            player.platform,
398	   398	            &player.id,
399	   399	            &player.name,
400	   400	            i64::from(points),
401	   401	        )
402	   402	        .await?;
403	   403	        tracing::info!(
404	   404	            player = %player.name,
405	   405	            points,
406	   406	            total_points = score.total_points,
407	   407	            "Wordle points awarded"
408	   408	        );
409	   409	    }
410	   410	    Ok(awarded)
411	   411	}
