519	   519	struct GameRound<'a> {
520	   520	    word: [u8; 5],
521	   521	    players_votes: HashMap<Player, (Word, u32)>,
522	   522	    spell_checker: &'a HashSet<String>,
523	   523	    guess_position: u32,
524	   524	}
525	   525	
526	   526	type Word = [u8; 5];
527	   527	
528	   528	struct VoteIndexer {
529	   529	    votes: u32,
530	   530	    position_in_round: u32,
531	   531	}
532	   532	
533	   533	impl<'a> GameRound<'a> {
534	   534	    // Creates a new game round with a predefined word
535	   535	    // word MUST be 5 characters long
536	   536	    pub fn new(word: Word, spell_checker: &'a HashSet<String>) -> Self {
537	   537	        Self {
538	   538	            word,
539	   539	            players_votes: HashMap::new(),
540	   540	            spell_checker,
541	   541	            guess_position: 0,
542	   542	        }
543	   543	    }
544	   544	
545	   545	    pub fn new_guess(&mut self, player: Player, guess: String) -> bool {
546	   546	        let upper = guess.to_uppercase();
547	   547	        if !self.validate_guess(&upper) {
548	   548	            return false;
549	   549	        }
550	   550	        self.guess_position += 1;
551	   551	        let mut arrays_of_u8 = Word::default();
552	   552	        arrays_of_u8.copy_from_slice(upper.as_bytes());
553	   553	        self.players_votes
554	   554	            .insert(player, (arrays_of_u8, self.guess_position));
555	   555	        true
556	   556	    }
557	   557	
558	   558	    // Validate guess
559	   559	    pub fn validate_guess(&self, guess: &str) -> bool {
560	   560	        if guess.len() != 5 {
561	   561	            return false;
562	   562	        }
563	   563	
564	   564	        if guess.contains(' ') {
565	   565	            return false;
566	   566	        }
567	   567	
568	   568	        // Check if the guess is in the spell checker
569	   569	        if !self.spell_checker.contains(&guess.to_uppercase()) {
570	   570	            return false;
571	   571	        }
572	   572	
573	   573	        // Check if the guess is a valid word
574	   574	        // For now, we just check if it contains only ASCII characters
575	   575	        guess.is_ascii()
576	   576	    }
577	   577	
578	   578	    pub fn build_cells(&self, guess: Word) -> RowMessage {
579	   579	        let mut cells = [Cell::default(); 5];
580	   580	        let mut letter_counts = HashMap::new();
581	   581	
582	   582	        // First pass: mark Correct and count leftover letters
583	   583	        for i in 0..5 {
584	   584	            if guess[i] == self.word[i] {
585	   585	                cells[i] = (guess[i], LetterStatus::Correct).into();
586	   586	            } else {
587	   587	                letter_counts
588	   588	                    .entry(self.word[i])
589	   589	                    .and_modify(|count| *count += 1)
590	   590	                    .or_insert(1);
591	   591	            }
592	   592	        }
593	   593	
594	   594	        // Second pass: mark Present or Absent
595	   595	        for i in 0..5 {
596	   596	            if cells[i].status == LetterStatus::Correct {
597	   597	                continue;
598	   598	            }
599	   599	
600	   600	            if let Some(count) = letter_counts.get_mut(&guess[i]) {
601	   601	                if *count > 0 {
602	   602	                    cells[i] = (guess[i], LetterStatus::Present).into();
603	   603	                    *count -= 1;
604	   604	                } else {
605	   605	                    cells[i] = (guess[i], LetterStatus::Absent).into();
606	   606	                }
607	   607	            } else {
608	   608	                cells[i] = (guess[i], LetterStatus::Absent).into();
609	   609	            }
610	   610	        }
611	   611	
612	   612	        RowMessage { data: cells }
613	   613	    }
614	   614	
615	   615	    // Select the winning guess based on the votes
616	   616	    pub fn select_round_winner(&self, word: Word) -> Option<Word> {
617	   617	        // If there are multiple words with the same number of votes, first check to see if any of
618	   618	        // them are the correct word, and pick that word.
619	   619	        // Second if there are no correct words, pick the lowest position word with the most votes.
620	   620	        let mut total_votes = HashMap::new();
621	   621	        let mut highest_vote = 0;
622	   622	
623	   623	        // Build a map of all votes
624	   624	        for (voted_word, pos) in self.players_votes.values() {
625	   625	            let votes = total_votes.entry(*voted_word).or_insert(VoteIndexer {
626	   626	                votes: 0,
627	   627	                position_in_round: 10000,
628	   628	            });
629	   629	            votes.votes += 1;
630	   630	            if pos < &votes.position_in_round {
631	   631	                votes.position_in_round = *pos;
632	   632	            }
633	   633	            if votes.votes > highest_vote {
634	   634	                highest_vote = votes.votes;
635	   635	            }
636	   636	        }
637	   637	
638	   638	        // Find the word with the most votes
639	   639	        // If there is a tie, pick the word with the lowest position in the round
640	   640	        let mut winning_word = ([0; 5], 1000000);
641	   641	        for (voted_word, vote_indexer) in total_votes.iter() {
642	   642	            if vote_indexer.votes == highest_vote {
643	   643	                // Check if the voted word is the correct word
